import{_ as a,o as t,c as i,au as o}from"./chunks/framework.BTTEhLNX.js";const k=JSON.parse('{"title":"krawler-openradiation","description":"A Krawler based service to download data from the OpenRadiation project.","frontmatter":{"title":"krawler-openradiation","description":"A Krawler based service to download data from the OpenRadiation project."},"headers":[],"relativePath":"packages/krawler-openradiation/index.md","filePath":"packages/krawler-openradiation/index.md"}'),r={name:"packages/krawler-openradiation/index.md"};function n(d,e,s,l,p,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler-openradiation" tabindex="-1">krawler-openradiation <a class="header-anchor" href="#krawler-openradiation" aria-label="Permalink to &quot;krawler-openradiation&quot;">​</a></h1><p><em>A Krawler based service to download data from the OpenRadiation project.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>krawler-openradiation</strong> job scrapes measurements from the <a href="https://github.com/openradiation/openradiation-api" target="_blank" rel="noreferrer">OpenRadiation API</a>. The downloaded data are stored within a <a href="https://www.mongodb.com/" target="_blank" rel="noreferrer">MongoDB</a> database and more precisely in a collection named <code>openradiation</code>.</p><p>All records are stored in <a href="https://fr.wikipedia.org/wiki/GeoJSON" target="_blank" rel="noreferrer">GeoJson</a> format.</p><p>The job is executed according a specific cron expression. By default, every hour.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>KEY</code></td><td>The key to use the API. As mentioned <a href="https://www.openradiation.org/en/developers" target="_blank" rel="noreferrer">here</a>, you should ask this access code to the <strong>OpenRadiation</strong> team.</td></tr><tr><td><code>DB_URL</code></td><td>The mongoDB database URL. The default value is <code>mongodb://127.0.0.1:27017/openradiation</code></td></tr><tr><td><code>COLLECTION</code></td><td>The mongoDB database collection. The default value is <code>openradiation</code></td></tr><tr><td><code>DATE_OF_CREATION</code></td><td>Force the date of measurements to be retrieved. Undefined by default so that the current date will be used.</td></tr><tr><td><code>TTL</code></td><td>The measurements data time to live. It must be expressed in seconds and the default value is <code>604 800</code> (7 days)</td></tr><tr><td><code>DEBUG</code></td><td>Enables debug output. Set it to <code>krawler*</code> to enable full output. By default it is undefined.</td></tr></tbody></table><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>We personally use <a href="https://kalisio.github.io/kargo/" target="_blank" rel="noreferrer">Kargo</a> to deploy the service.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install with your preferred package manager:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-w1KYB" id="tab-_IgaAcf" checked><label data-title="pnpm" for="tab-_IgaAcf">pnpm</label><input type="radio" name="group-w1KYB" id="tab-JVLoKl8"><label data-title="npm" for="tab-JVLoKl8">npm</label><input type="radio" name="group-w1KYB" id="tab-0LTPsgU"><label data-title="yarn" for="tab-0LTPsgU">yarn</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler-openradiation</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler-openradiation</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler-openradiation</span></span></code></pre></div></div></div>',13)])])}const b=a(r,[["render",n]]);export{k as __pageData,b as default};
